import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth, LANG_LIST } from '../App';

const LANG_META = {
  en:{native:'English',flag:'🇬🇧'}, hi:{native:'हिंदी',flag:'🇮🇳'}, mr:{native:'मराठी',flag:'🌾'},
  pa:{native:'ਪੰਜਾਬੀ',flag:'🌻'}, te:{native:'తెలుగు',flag:'🌴'}, bn:{native:'বাংলা',flag:'🐯'},
  gu:{native:'ગુજરાતી',flag:'🦁'}, ta:{native:'தமிழ்',flag:'🌺'}, kn:{native:'ಕನ್ನಡ',flag:'🐘'},
  or:{native:'ଓଡ଼ିଆ',flag:'🌊'}, ur:{native:'اردو',flag:'🌙'},
};

const CROPS  = ['Wheat','Rice','Cotton','Sugarcane','Maize','Soybean','Tomato','Onion'];
const STATES = ['Maharashtra','Punjab','Uttar Pradesh','Madhya Pradesh','Rajasthan','Gujarat','Karnataka','Andhra Pradesh'];

export default function AuthPage() {
  const [tab, setTab]       = useState('login');
  const [form, setForm]     = useState({ name:'', phone:'', password:'', state:'', crop:'', acres:'' });
  const [locating, setLocating] = useState(false);
  const [location, setLocation] = useState(null);
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState('');
  const { setUser, lang } = useAuth();
  const navigate = useNavigate();
  const langMeta = LANG_META[lang] || LANG_META.en;

  const detectGPS = () => {
    setLocating(true);
    navigator.geolocation?.getCurrentPosition(
      pos => { setLocation({ lat: pos.coords.latitude.toFixed(4), lng: pos.coords.longitude.toFixed(4) }); setLocating(false); },
      ()  => { setLocation({ lat: '18.5204', lng: '73.8567' }); setLocating(false); }
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault(); setError('');
    if (!form.phone || !form.password) { setError('Please fill all required fields.'); return; }
    setLoading(true);
    setTimeout(() => {
      setUser({ name: form.name || 'Farmer', phone: form.phone, state: form.state || 'India', crop: form.crop, acres: form.acres, gps: location });
      setLoading(false);
      navigate('/dashboard');
    }, 1000);
  };

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md animate-slide-up">

        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2.5 mb-3">
            <div className="w-11 h-11 rounded-xl btn-primary flex items-center justify-center text-xl">🌿</div>
            <span className="font-display font-bold text-2xl text-slate-800">
              SmartSheti <span className="text-brand-600">AI</span>
            </span>
          </div>
          <p className="text-slate-500 text-sm mb-3">India's Smartest Farming Platform</p>
          <div className="flex items-center justify-center gap-2">
            <span className="badge badge-green text-xs">
              <span>{langMeta.flag}</span> {langMeta.native}
            </span>
            <button
              onClick={() => navigate('/select-language')}
              className="text-brand-600 hover:text-brand-700 text-xs font-medium underline underline-offset-2"
            >
              Change
            </button>
          </div>
        </div>

        {/* Card */}
        <div className="card p-8 shadow-card-lg">
          {/* Tabs */}
          <div className="flex bg-slate-100 rounded-xl p-1 mb-7 gap-1">
            {['login','register'].map(t => (
              <button
                key={t}
                onClick={() => setTab(t)}
                className={`flex-1 py-2.5 rounded-lg text-sm font-semibold transition-all capitalize
                  ${tab === t ? 'bg-white text-brand-700 shadow-card' : 'text-slate-500 hover:text-slate-700'}`}
              >
                {t === 'login' ? '🔑 Login' : '🌱 Register'}
              </button>
            ))}
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {tab === 'register' && (
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">Full Name</label>
                <input value={form.name} onChange={e => set('name', e.target.value)} placeholder="Ramesh Kumar"
                  className="w-full px-4 py-2.5 text-sm" />
              </div>
            )}

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">Phone Number *</label>
              <input value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="+91 98765 43210" type="tel"
                className="w-full px-4 py-2.5 text-sm" />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">Password *</label>
              <input value={form.password} onChange={e => set('password', e.target.value)} placeholder="••••••••" type="password"
                className="w-full px-4 py-2.5 text-sm" />
            </div>

            {tab === 'register' && (
              <>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">State</label>
                    <select value={form.state} onChange={e => set('state', e.target.value)} className="w-full px-3 py-2.5 text-sm">
                      <option value="">Select</option>
                      {STATES.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">Main Crop</label>
                    <select value={form.crop} onChange={e => set('crop', e.target.value)} className="w-full px-3 py-2.5 text-sm">
                      <option value="">Select</option>
                      {CROPS.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">Farm Size (Acres)</label>
                  <input value={form.acres} onChange={e => set('acres', e.target.value)} placeholder="e.g. 5" type="number"
                    className="w-full px-4 py-2.5 text-sm" />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-1.5">GPS Location</label>
                  <button type="button" onClick={detectGPS}
                    className={`w-full btn-secondary py-2.5 text-sm rounded-lg flex items-center justify-center gap-2 ${locating ? 'opacity-60' : ''}`}>
                    {locating
                      ? <><span className="animate-spin">⟳</span> Detecting...</>
                      : location
                        ? <>📍 {location.lat}, {location.lng}</>
                        : <>📍 Detect My Location</>
                    }
                  </button>
                </div>
              </>
            )}

            {error && (
              <div className="card-red px-4 py-2.5 text-red-700 text-sm text-center rounded-xl">{error}</div>
            )}

            <button type="submit" disabled={loading}
              className={`w-full btn-primary py-3.5 rounded-xl text-base font-semibold flex items-center justify-center gap-2 mt-1 ${loading ? 'opacity-70' : ''}`}>
              {loading
                ? <><span className="animate-spin text-lg">⟳</span> Processing...</>
                : tab === 'login' ? '🔑 Login to Dashboard' : '🌱 Create My Farm Account'
              }
            </button>
          </form>

          <p className="text-center text-slate-400 text-xs mt-6">
            {tab === 'login' ? "Don't have an account? " : 'Already registered? '}
            <button onClick={() => setTab(tab === 'login' ? 'register' : 'login')} className="text-brand-600 hover:text-brand-700 font-semibold">
              {tab === 'login' ? 'Register Free' : 'Login'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
}
